import type { DescMessage, MessageShape } from '@bufbuild/protobuf'

import { fromBinary } from '@bufbuild/protobuf'
import { BinaryReader, WireType } from '@bufbuild/protobuf/wire'
import { AnySchema, anyUnpack } from '@bufbuild/protobuf/wkt'

/**
 * Reads a typed detail from a serialized google.rpc.Status.
 * NOTICE: Status is not generated by this SDK. Field 3 contains repeated Any
 * values. Unknown and malformed details leave the original RPC error intact.
 */
export function rpcDetail<T extends DescMessage>(
  details: Uint8Array,
  schema: T,
  accepts: (detail: MessageShape<T>) => boolean = () => true,
): MessageShape<T> | undefined {
  try {
    const reader = new BinaryReader(details)
    while (reader.pos < reader.len) {
      const [field, wireType] = reader.tag()
      if (field !== 3 || wireType !== WireType.LengthDelimited) {
        reader.skip(wireType)
        continue
      }
      const detail = anyUnpack(fromBinary(AnySchema, reader.bytes()), schema)
      if (detail !== undefined && accepts(detail))
        return detail
    }
  }
  catch {
    return undefined
  }
  return undefined
}
